import{_ as t,l as s,o as e,c as i,v as l,p as d,x as r,d as n,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Flush+Reload","description":"","frontmatter":{"title":"Flush+Reload","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/flush-reload.md","filePath":"cs/flush-reload.md","lastUpdated":1789023840000}'),c={name:"cs/flush-reload.md"};function u(m,a,_,E,f,A){const o=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=l('<h1 id="flush-reload" tabindex="-1">Flush+Reload <a class="header-anchor" href="#flush-reload" aria-label="Permalink to &quot;Flush+Reload&quot;">​</a></h1><div class="epigraph"><p>共享页（含共享库）上，驱逐再等待再测加载时间，可推断别人是否访问了该行。这是缓存侧信道的经典形状：共享是特性，也是通道。</p><footer>—— Yarom and Falkner, Flush+Reload, USENIX Security 2014</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/rowhammer-mitigations">Rowhammer</a>扰动存储。缺口是<strong>共享缓存当通道</strong>。主干侧信道已警告时间。本课点名 Flush+Reload 作为机制名字，不给测密钥步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>dedup 与共享 libc 创造共享行。高分辨率计时。缺口是：禁共享、降计时精度、常数时间密码、隔离核。</p><h3 id="云共驻" tabindex="-1">云共驻 <a class="header-anchor" href="#云共驻" aria-label="Permalink to &quot;云共驻&quot;">​</a></h3><p>同主机租户是模型里的观察者。</p><p><span class="marginnote">Yarom–Falkner 2014。禁止还原密钥的实验指导。VM 逃逸下一课换隔离边界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述共享+计时。对策。下一课虚拟机逃逸：逻辑边界而非缓存。</p>',12)),(e(),d(p,null,{default:r(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHARE%5B%22%E5%85%B1%E4%BA%AB%E8%A1%8C%22%5D%20--%3E%20FLUSH%5B%22%E9%A9%B1%E9%80%90%22%5D%0A%20%20FLUSH%20--%3E%20TIME%5B%22%E5%86%8D%E5%8A%A0%E8%BD%BD%E8%AE%A1%E6%97%B6%22%5D%0A%20%20TIME%20--%3E%20INF%5B%22%E6%8E%A8%E6%96%AD%E4%BB%96%E4%BA%BA%E8%AE%BF%E9%97%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>C 可经缓存泄漏。VM 逃逸下一课是完整性：从客到宿。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写测量配方。虚拟机逃逸下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Rowhammer 翻比特；Flush+Reload 测共享行时间。</li><li>共享库与去重是通道来源。</li><li>常数时间与隔离是对策。</li><li>下一课 VM 逃逸。</li><li>出处：Yarom and Falkner, 2014；<a href="/cs/side-channel">side-channel</a>。</li></ul>',8))])}const T=t(c,[["render",u]]);export{b as __pageData,T as default};
